def check(output: str, ctx: dict) -> bool:
    obj = parse_json(output)
    if obj is None:
        return False
    tokens = ctx['text'].split()
    contains_named_entity = any(token[0].isupper() for token in tokens if token.isalpha())
    if contains_named_entity:
        return any(obj[field] for field in ['person', 'location', 'organization', 'else'])
    return True

